'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE=(process.env.P14_BASE_URL||'https://plan-ex.ru/erpv2/').replace(/\/+$/,'/'),U=p=>new URL(p,BASE).href;
const OUT=path.resolve(process.env.P14_OUT_DIR||'P14_output'),SHOTS=path.join(OUT,'P14_DATA_SCREENSHOTS');fs.mkdirSync(SHOTS,{recursive:true});
const COMPANY_ID=27,OWNER='p14_owner_260804221827';
function runtimeCreds(){const e=process.env.P11_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function superadmin(){return runtimeCreds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
function today(add=0){return new Date(Date.now()+add*86400000).toISOString().slice(0,10)}
function inn10(seed){const s=String(seed).replace(/\D/g,'').padStart(9,'0').slice(-9),a=[...s].map(Number),w=[2,4,10,3,5,9,4,6,8];return s+((a.reduce((z,x,i)=>z+x*w[i],0)%11)%10)}
async function tryLogin(browser,u,pw){const c=await browser.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,ignoreHTTPSErrors:true,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded',timeout:45000});await p.locator('input[name="username"],input[name="email"],input[type="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').first().fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded',{timeout:12000}).catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(500);ok=!/\/login(?:[/?#]|$)/i.test(p.url())}catch{}return{ok,context:c,page:p}}
function candidates(text,vals,u){const o=[];for(const v of vals)o.push(String(v));for(const m of String(text||'').matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))o.push(m[0]);return[...new Set(o)].filter(v=>v.length>=8&&v.length<=64&&v!==u&&!v.includes('@example.test')&&!/^\+?7\d{10}$/.test(v)&&!/^[a-f0-9]{64}$/i.test(v))}
async function resetOwner(browser){const s=superadmin();if(!s)throw Error('superadmin unavailable');const x=await tryLogin(browser,s.username,s.password);if(!x.ok)throw Error('superadmin login failed');const p=x.page;await p.goto(U(`superadmin/companies/${COMPANY_ID}/users`),{waitUntil:'domcontentloaded',timeout:45000});const f=p.locator(`form[action$="/superadmin/companies/${COMPANY_ID}/owner/reset-password"]`).first();if(!(await f.count()))throw Error('owner reset form missing');const nav=p.waitForNavigation({waitUntil:'domcontentloaded',timeout:30000});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await nav;await p.waitForTimeout(400);const vals=await p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(n=>n.value||n.getAttribute('data-password')||n.textContent||'').filter(Boolean));const list=candidates(await p.locator('body').innerText().catch(()=>''),vals,OWNER);await x.context.close();for(const candidate of list){const t=await tryLogin(browser,OWNER,candidate);if(t.ok){for(let i=0;i<list.length;i++)list[i]='';return{password:candidate,context:t.context,page:t.page}}await t.context.close()}throw Error('owner reset password verification failed')}
async function fill(form,name,value){const l=form.locator(`[name="${name.replace(/"/g,'\\"')}"]`).first();if(!(await l.count()))return false;const tag=await l.evaluate(e=>e.tagName);if(tag==='SELECT'){await l.selectOption(String(value)).catch(async()=>{const opts=await l.locator('option').evaluateAll(os=>os.map(o=>o.value).filter(Boolean));if(opts.length)await l.selectOption(opts[0])})}else if((await l.getAttribute('type'))!=='file')await l.fill(String(value));return true}
async function submit(page,form){const nav=page.waitForNavigation({waitUntil:'domcontentloaded',timeout:30000}).catch(()=>null);await form.evaluate(f=>f.requestSubmit());const r=await nav;await page.waitForTimeout(600);return r}
const specs={client:{list:'company/clients',attr:'data-client-id'},contractor:{list:'company/contractors',attr:'data-contractor-id'},driver:{list:'company/drivers',attr:'data-driver-id'},vehicle:{list:'company/vehicle-sets',attr:'data-vehicle-set-id'},executor:{list:'company/route-executors',attr:'data-route-executor-id'},trip:{list:'company/trips/linear',attr:'data-linear-route-id'}};
async function findId(page,type,label){const s=specs[type];await page.goto(U(s.list),{waitUntil:'domcontentloaded',timeout:45000});await page.waitForTimeout(400);let row=page.locator(`[${s.attr}]`).filter({hasText:label}).first();if(await row.count()){const v=await row.getAttribute(s.attr);if(v)return Number(v)}const generic=page.locator('tr,[data-id]').filter({hasText:label}).first();if(await generic.count()){const attrs=await generic.evaluate(e=>Object.fromEntries([...e.attributes].map(a=>[a.name,a.value])));for(const [k,v] of Object.entries(attrs))if(/data-.*-id$/.test(k)&&/^\d+$/.test(v))return Number(v);const first=(await generic.locator('td').first().innerText().catch(()=>'' )).trim();if(/^\d+$/.test(first))return Number(first)}return null}
async function createLegal(page,type,name,inn,result,filePath){let existing=await findId(page,type,name);if(existing){result.steps.push({step:`reuse_${type}`,pass:true,id:existing});return existing}const list=specs[type].list,trigger=type==='client'?/Создать клиента/i:/Создать перевозчика/i,action=type==='client'?'/company/clients/create':'/company/contractors/create';await page.goto(U(list),{waitUntil:'domcontentloaded',timeout:45000});await page.locator('button,a').filter({hasText:trigger}).first().click();await page.waitForTimeout(500);const form=page.locator(`form[action$="${action}"]`).first();await fill(form,'name',name);await fill(form,'inn',inn);await fill(form,type==='client'?'entity_type':'contractor_type','legal_entity');await fill(form,'kpp','770101001');await fill(form,'director_full_name','Тестов Контакт П14');await fill(form,'director_position','Директор');await fill(form,'legal_address','127000, Москва, Тестовая улица, 14');await fill(form,'physical_address','127000, Москва, Тестовая улица, 14');await fill(form,'contacts[0][contact_person]','Тестов Контакт П14');await fill(form,'contacts[0][phone]',type==='client'?'+79990001411':'+79990001412');await fill(form,'contacts[0][email]',`${type}.p14@example.test`);await fill(form,'comments','P14 isolated synthetic record');const add=form.locator('button').filter({hasText:/Добавить документ/i}).first();if(await add.count()){await add.click();await page.waitForTimeout(300);const input=form.locator('input[type="file"]').first();if(await input.count())await input.setInputFiles(filePath).catch(()=>{})}const r=await submit(page,form);const id=await findId(page,type,name);result.steps.push({step:`create_${type}`,httpStatus:r?.status()??null,pass:!!id,id});if(!id)throw Error(`${type} id missing`);await page.screenshot({path:path.join(SHOTS,`P14_${type.toUpperCase()}_CREATED_1920x1080.png`),fullPage:false});return id}
async function createDriver(page,result,filePath){const name='П14 Водитель Тестовый';let id=await findId(page,'driver',name);if(id){result.steps.push({step:'reuse_driver',pass:true,id});return id}await page.goto(U('company/drivers'),{waitUntil:'domcontentloaded'});await page.locator('button,a').filter({hasText:/Добавить нового водителя/i}).first().click();await page.waitForTimeout(400);const f=page.locator('#driver-create-form').first();await fill(f,'full_name',name);await fill(f,'phone','+79990001421');await fill(f,'passport_number','4514 140014');await fill(f,'license_number','7714 001414');await fill(f,'email','driver.p14@example.test');await fill(f,'comments','P14 isolated synthetic driver');const add=f.locator('button').filter({hasText:/Добавить документ/i}).first();if(await add.count()){await add.click();const inp=f.locator('input[type="file"]').first();if(await inp.count())await inp.setInputFiles(filePath).catch(()=>{})}const r=await submit(page,f);id=await findId(page,'driver',name);result.steps.push({step:'create_driver',httpStatus:r?.status()??null,pass:!!id,id});if(!id)throw Error('driver id missing');await page.screenshot({path:path.join(SHOTS,'P14_DRIVER_CREATED_1920x1080.png'),fullPage:false});return id}
async function createVehicle(page,result,filePath){const plate='Т014СТ77';let id=await findId(page,'vehicle',plate);if(id){result.steps.push({step:'reuse_vehicle',pass:true,id});return id}await page.goto(U('company/vehicle-sets'),{waitUntil:'domcontentloaded'});await page.locator('button,a').filter({hasText:/Добавить|Создать/i}).first().click();await page.waitForTimeout(400);const f=page.locator('#vehicle-set-create-form').first();await fill(f,'set_type','single');await page.waitForTimeout(600);await fill(f,'units[primary][brand]','КАМАЗ');await fill(f,'units[primary][model]','5490');await fill(f,'units[primary][plate_number]',plate);await fill(f,'units[primary][vin]','XTC54900000000014');await fill(f,'units[primary][diagnostic_card_number]','P14-DC-0014');await fill(f,'units[primary][diagnostic_card_date]',today(-10));await fill(f,'units[primary][capacity_tons]','20');await fill(f,'units[primary][volume_m3]','82');await fill(f,'comments','P14 isolated synthetic vehicle');for(const n of ['predef_doc[primary][sts][]','predef_doc[primary][photo][]']){const i=f.locator(`[name="${n}"]`).first();if(await i.count())await i.setInputFiles(filePath)}const r=await submit(page,f);id=await findId(page,'vehicle',plate);result.steps.push({step:'create_vehicle',httpStatus:r?.status()??null,pass:!!id,id});if(!id)throw Error('vehicle id missing');await page.screenshot({path:path.join(SHOTS,'P14_VEHICLE_CREATED_1920x1080.png'),fullPage:false});return id}
async function createExecutor(page,cid,did,vid,result){const label='П14 Водитель Тестовый';let id=await findId(page,'executor',label);if(id){result.steps.push({step:'reuse_executor',pass:true,id});return id}await page.goto(U('company/route-executors'),{waitUntil:'domcontentloaded'});await page.locator('button,a').filter({hasText:/Создать|Добавить/i}).first().click();await page.waitForTimeout(400);const f=page.locator('#route-executor-create-form').first();await fill(f,'contractor_id',cid);await fill(f,'driver_id',did);await fill(f,'vehicle_set_id',vid);await fill(f,'comments','P14 isolated executor');const r=await submit(page,f);id=await findId(page,'executor',label);result.steps.push({step:'create_executor',httpStatus:r?.status()??null,pass:!!id,id});if(!id)throw Error('executor id missing');await page.screenshot({path:path.join(SHOTS,'P14_EXECUTOR_CREATED_1920x1080.png'),fullPage:false});return id}
async function createTrip(page,client,contractor,executor,result,filePath){let id=await findId(page,'trip','P14 Тестовый безопасный груз');if(id){result.steps.push({step:'reuse_trip',pass:true,id});return id}await page.goto(U('company/trips/linear?show_create=1'),{waitUntil:'domcontentloaded',timeout:45000});const f=page.locator('#linear-trip-create-form').first();await fill(f,'route_type','linear');await fill(f,'planned_loading_date',today(2));await fill(f,'client_id',client);await fill(f,'carrier_contractor_id',contractor);await fill(f,'route_executor_id',executor);await fill(f,'cargo_type_name','P14 Тестовый безопасный груз');await fill(f,'customer_payments[0][amount]','120000');await fill(f,'customer_payments[0][payment_method]','cashless');await fill(f,'customer_payments[0][condition_type]','prepayment');await fill(f,'carrier_payments[0][amount]','85000');await fill(f,'carrier_payments[0][payment_method]','cashless');await fill(f,'carrier_payments[0][condition_type]','after_end');await fill(f,'carrier_payments[0][days_count]','5');await fill(f,'carrier_payments[0][days_kind]','working');await fill(f,'comments','P14 isolated representative trip');for(const n of ['customer_document','carrier_document']){const i=f.locator(`[name="${n}"]`).first();if(await i.count())await i.setInputFiles(filePath)}const r=await submit(page,f);id=await findId(page,'trip','P14 Тестовый безопасный груз');result.steps.push({step:'create_trip',httpStatus:r?.status()??null,pass:!!id,id});await page.screenshot({path:path.join(SHOTS,'P14_TRIP_CREATED_1920x1080.png'),fullPage:false});return id}
async function createFinance(page,clientId,result){await page.goto(U('company/finance/settings/dds-categories'),{waitUntil:'domcontentloaded'});const body=await page.locator('body').innerText();if(!body.includes('P14_AUDIT')){const cb=page.locator('button,a').filter({hasText:/Создать статью/i}).first();if(await cb.count()){await cb.click();await page.waitForTimeout(300);const f=page.locator('form[action$="/company/finance/settings/dds-categories/create"]').first();await fill(f,'code','P14_AUDIT');await fill(f,'name','P14 Аудит тестовой компании');await fill(f,'direction','BOTH');await fill(f,'sort_order','1400');const rr=await submit(page,f);result.steps.push({step:'create_dds',httpStatus:rr?.status()??null,pass:true})}}else result.steps.push({step:'reuse_dds',pass:true});await page.goto(U('company/finance/cash'),{waitUntil:'domcontentloaded'});const cashText=await page.locator('body').innerText();if(!cashText.includes('P14 тестовое внесение')){const ib=page.locator('button,a').filter({hasText:/Внести|Приход/i}).first();if(await ib.count()){await ib.click();await page.waitForTimeout(300);const f=page.locator('form[action$="/company/finance/cash/operation-create"]').first();await fill(f,'operation_type','INCOME');const acc=f.locator('[name="money_account_id"]');const opts=await acc.locator('option').evaluateAll(os=>os.map(o=>o.value).filter(Boolean));if(opts.length)await acc.selectOption(opts[0]);await fill(f,'amount','150000');await fill(f,'operation_date',today());await fill(f,'purpose','P14 тестовое внесение');await fill(f,'comment','Только тестовая компания 27');const rr=await submit(page,f);result.steps.push({step:'create_cash_income',httpStatus:rr?.status()??null,pass:true})}}else result.steps.push({step:'reuse_cash_income',pass:true});await page.goto(U('company/finance/invoices'),{waitUntil:'domcontentloaded'});const invText=await page.locator('body').innerText();if(!invText.includes('P14-INV-001')){const b=page.locator('button,a').filter({hasText:/Создать счёт/i}).first();if(await b.count()){await b.click();await page.waitForTimeout(300);const f=page.locator('form[action$="/company/finance/invoices/create"]').first();await fill(f,'direction','OUTGOING');await fill(f,'number','P14-INV-001');await fill(f,'invoice_date',today());await fill(f,'counterparty_entity_type','client');await page.waitForTimeout(400);await fill(f,'counterparty_entity_id',clientId);await fill(f,'counterparty_name','P14 Клиент Аудит');await fill(f,'amount','120000');await fill(f,'planned_payment_date',today(7));await fill(f,'basis','P14 тестовый рейс и услуги');await fill(f,'status','issued');await fill(f,'comment','Только тестовая компания 27');const rr=await submit(page,f);result.steps.push({step:'create_invoice',httpStatus:rr?.status()??null,pass:true})}}else result.steps.push({step:'reuse_invoice',pass:true});await page.goto(U('company/finance/dashboard'),{waitUntil:'domcontentloaded'});await page.screenshot({path:path.join(SHOTS,'P14_FINANCE_DASHBOARD_AFTER_DATA_1920x1080.png'),fullPage:false})}
async function crudClient(page,id,tempId,result){await page.goto(U(`company/clients/${id}`),{waitUntil:'domcontentloaded'});const e=page.locator('a,button').filter({hasText:/Редактировать/i}).first();if(await e.count()){await e.click();await page.waitForTimeout(300);const f=page.locator('form').filter({has:page.locator('[name="name"]')}).first();if(await f.count()){await fill(f,'comments','P14 CRUD UPDATE PASS');const rr=await submit(page,f);result.steps.push({step:'update_client',httpStatus:rr?.status()??null,pass:true})}}else result.steps.push({step:'update_client',pass:false,note:'edit unavailable'});await page.goto(U(`company/clients/${tempId}`),{waitUntil:'domcontentloaded'});const d=page.locator('button,a').filter({hasText:/Удалить/i}).first();if(await d.count()){page.once('dialog',x=>x.accept());await d.click();await page.waitForTimeout(400);const f=page.locator('form').filter({has:page.locator('button').filter({hasText:/Удалить|Подтвердить/i})}).first();if(await f.count())await submit(page,f);result.steps.push({step:'delete_temp_client',pass:true})}else result.steps.push({step:'delete_temp_client',pass:false,note:'delete unavailable'})}
(async()=>{const result={status:'FAIL',companyId:COMPANY_ID,entities:{},steps:[],consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],errors:[]};let browser,owner;try{const png=path.join(OUT,'P14_test_document.png');fs.writeFileSync(png,Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl2nXQAAAAASUVORK5CYII=','base64'));browser=await chromium.launch({headless:true});owner=await resetOwner(browser);const p=owner.page;p.on('console',m=>{if(m.type()==='error')result.consoleErrors.push(m.text())});p.on('pageerror',e=>result.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>result.requestFailures.push(`${q.method()} ${q.url()} ${q.failure()?.errorText||''}`));p.on('response',r=>{if(r.status()>=400)result.httpFailures.push(`${r.status()} ${r.url()}`)});const seed=Date.now();result.entities.clientId=await createLegal(p,'client','P14 Клиент Аудит',inn10(seed),result,png);result.entities.tempClientId=await createLegal(p,'client','P14 Клиент Удаление',inn10(seed+31),result,png);result.entities.contractorId=await createLegal(p,'contractor','P14 Перевозчик Аудит',inn10(seed+67),result,png);result.entities.driverId=await createDriver(p,result,png);result.entities.vehicleSetId=await createVehicle(p,result,png);result.entities.routeExecutorId=await createExecutor(p,result.entities.contractorId,result.entities.driverId,result.entities.vehicleSetId,result);result.entities.tripId=await createTrip(p,result.entities.clientId,result.entities.contractorId,result.entities.routeExecutorId,result,png);await createFinance(p,result.entities.clientId,result);await crudClient(p,result.entities.clientId,result.entities.tempClientId,result);await p.goto(U('company/dashboard'),{waitUntil:'domcontentloaded'});await p.screenshot({path:path.join(SHOTS,'P14_TEST_TENANT_FINAL_DASHBOARD_1920x1080.png'),fullPage:false});result.status=result.steps.some(x=>x.pass===false)?'PASS_WITH_NONBLOCKING_LIMITATIONS':'PASS';owner.password=''}catch(e){result.errors.push({name:e?.name||'Error',message:String(e?.message||e).replace(/[A-Za-z0-9!@#$%^&*()_+\-=]{12,}/g,'[REDACTED]').slice(0,700)})}finally{if(owner?.context)await owner.context.close().catch(()=>{});if(browser)await browser.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P14_runtime_result.json'),JSON.stringify(result,null,2));console.log(`P14_DATA_SETUP=${result.status}`);process.exitCode=result.status.startsWith('PASS')?0:1}})();
